// Package generate turns the configuration into Git configuration files:
// one snippet per profile and a rules index of include/includeIf entries.
//
// Precedence is encoded by order, because Git lets later settings override
// earlier ones: the default profile comes first, then directory rules from
// least to most specific, then pins.
package generate

import (
	"cmp"
	"fmt"
	"path"
	"slices"
	"strings"

	"github.com/weikxs/gitpersona/internal/config"
	"github.com/weikxs/gitpersona/internal/paths"
)

// Generated file names, relative to the configuration directory.
const (
	RulesFile   = "rules.gitconfig"
	profilesDir = "profiles"
)

const header = "# Generated by GitPersona from config.toml. Do not edit: run `gitpersona apply`.\n"

// Options carries everything the generator needs from the environment.
type Options struct {
	Home            string
	ConfigDir       string
	Executable      string // absolute path of the gitpersona binary
	CaseInsensitive bool
	// FallbackSSHCommand restores the user's core.sshCommand for profiles
	// without an SSH key. Empty means plain "ssh".
	FallbackSSHCommand string
	// FallbackSigning restores the user's own signing settings for profiles
	// without signing. Empty fields are not restored; signing is then off.
	FallbackSigning Signing
	// Canonicalize, if set, resolves symbolic links in a path. Git matches
	// includeIf against the real path of the repository, so when a rule's
	// directory goes through a symlink an entry for the real path is added.
	Canonicalize func(string) string
}

// Signing holds the user's global commit-signing settings.
type Signing struct {
	GPGSign    string // commit.gpgsign
	SigningKey string // user.signingkey
	Format     string // gpg.format
}

// File is one generated file.
type File struct {
	Name    string // relative to Options.ConfigDir
	Content string
}

// ProfileFile returns the generated file name for a profile.
func ProfileFile(id string) string {
	return path.Join(profilesDir, id+".gitconfig")
}

// Generate validates cfg and returns every generated file, sorted by name.
func Generate(cfg config.Config, opts Options) ([]File, error) {
	if err := cfg.Validate(opts.Home, opts.CaseInsensitive); err != nil {
		return nil, fmt.Errorf("invalid configuration: %w", err)
	}

	usage := scanUsage(cfg)
	files := make([]File, 0, len(cfg.Profiles)+1)
	for _, p := range cfg.Profiles {
		content, err := profileSnippet(p, usage, opts)
		if err != nil {
			return nil, err
		}
		files = append(files, File{Name: ProfileFile(p.ID), Content: content})
	}
	files = append(files, File{Name: RulesFile, Content: rulesIndex(cfg, opts)})

	slices.SortFunc(files, func(a, b File) int { return cmp.Compare(a.Name, b.Name) })
	return files, nil
}

// usage records settings that some profile changes, so that profiles which
// do not use them must reset them instead of inheriting another profile's.
type usage struct {
	signing bool
	sshKeys bool
}

func scanUsage(cfg config.Config) usage {
	var u usage
	for _, p := range cfg.Profiles {
		u.signing = u.signing || p.Signing.Enabled()
		u.sshKeys = u.sshKeys || p.SSHKey != ""
	}
	return u
}

func profileSnippet(p config.Profile, u usage, opts Options) (string, error) {
	var b strings.Builder
	b.WriteString(header)
	fmt.Fprintf(&b, "# Profile %s: %s on %s\n", p.ID, p.Account, p.Host)

	b.WriteString("[user]\n")
	writeKV(&b, "name", p.Name)
	writeKV(&b, "email", p.Email)

	if err := writeSigning(&b, p, u, opts); err != nil {
		return "", err
	}
	if err := writeSSH(&b, p, u, opts); err != nil {
		return "", err
	}
	writeCredential(&b, p, opts)
	return b.String(), nil
}

func writeSigning(b *strings.Builder, p config.Profile, u usage, opts Options) error {
	if p.Signing.Method == config.SigningNone {
		// "none" means off, even when the user signs everything globally.
		b.WriteString("[commit]\n")
		writeKV(b, "gpgsign", "false")
		b.WriteString("[tag]\n")
		writeKV(b, "gpgSign", "false")
		return nil
	}
	if !p.Signing.Enabled() {
		if u.signing {
			writeFallbackSigning(b, opts.FallbackSigning, p.Email)
		}
		return nil
	}
	key := p.Signing.Key
	if p.Signing.Method == config.SigningSSH {
		expanded, err := paths.Normalize(key, opts.Home)
		if err != nil {
			return fmt.Errorf("profile %q signing key: %w", p.ID, err)
		}
		key = expanded
	}
	b.WriteString("[user]\n")
	writeKV(b, "signingkey", key)
	b.WriteString("[gpg]\n")
	writeKV(b, "format", map[string]string{config.SigningSSH: "ssh", config.SigningGPG: "openpgp"}[p.Signing.Method])
	b.WriteString("[commit]\n")
	writeKV(b, "gpgsign", "true")
	return nil
}

// writeFallbackSigning puts back the user's own signing settings, which
// another profile's signing would otherwise override. Without a key of their
// own, the key is the profile's email and the format GPG, which is what Git
// uses by default, so `git commit -S` never signs with another profile's
// key. A user who signs with SSH without a key (gpg.ssh.defaultKeyCommand)
// keeps that: Git cannot unset a key, so none is written.
func writeFallbackSigning(b *strings.Builder, s Signing, email string) {
	format := cmp.Or(s.Format, "openpgp")
	if s.SigningKey != "" || format != "ssh" {
		b.WriteString("[user]\n")
		writeKV(b, "signingkey", cmp.Or(s.SigningKey, email))
	}
	b.WriteString("[gpg]\n")
	writeKV(b, "format", format)
	b.WriteString("[commit]\n")
	writeKV(b, "gpgsign", cmp.Or(s.GPGSign, "false"))
}

func writeSSH(b *strings.Builder, p config.Profile, u usage, opts Options) error {
	if p.SSHKey == "" {
		if u.sshKeys {
			b.WriteString("[core]\n")
			writeKV(b, "sshCommand", cmp.Or(opts.FallbackSSHCommand, "ssh"))
		}
		return nil
	}
	key, err := paths.Normalize(p.SSHKey, opts.Home)
	if err != nil {
		return fmt.Errorf("profile %q ssh_key: %w", p.ID, err)
	}
	b.WriteString("[core]\n")
	writeKV(b, "sshCommand", "ssh -i "+shellQuote(key)+" -o IdentitiesOnly=yes")
	return nil
}

// writeCredential makes GitPersona the only credential helper for the
// profile's host. The user's own helpers are deliberately not chained after
// it: Git asks every helper to store a credential that worked, so a chained
// keychain or store helper would keep a copy of the gh token. Providers
// GitPersona does not handle yet get no credential section at all, so the
// user's helpers keep working for them.
func writeCredential(b *strings.Builder, p config.Profile, opts Options) {
	if p.Provider != config.ProviderGitHub {
		return
	}
	helper := fmt.Sprintf("!%s credential --provider %s --host %s --account %s",
		shellQuote(opts.Executable), p.Provider, shellQuote(p.Host), shellQuote(p.Account))

	fmt.Fprintf(b, "[credential %s]\n", quoteSubsection("https://"+p.Host))
	writeKV(b, "helper", "") // reset: no other helper may answer or store for this host
	writeKV(b, "helper", helper)
	writeKV(b, "username", p.Account)
}

func rulesIndex(cfg config.Config, opts Options) string {
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("# Order is precedence: default, then directory rules from least to most specific, then pins.\n")

	if cfg.Default != "" {
		fmt.Fprintf(&b, "\n# Default profile: %s\n[include]\n", cfg.Default)
		writeKV(&b, "path", opts.profilePath(cfg.Default))
	}

	gitdir := "gitdir:"
	if opts.CaseInsensitive {
		gitdir = "gitdir/i:"
	}
	for _, r := range sortedRules(cfg, opts.Home) {
		fmt.Fprintf(&b, "\n# Rule: %s -> %s\n", r.written, r.profile)
		opts.writeIncludeIf(&b, gitdir, r.norm, "/", r.profile)
	}
	for _, pin := range cfg.Pins {
		norm, _ := paths.Normalize(pin.Repo, opts.Home) // validated in Generate
		fmt.Fprintf(&b, "\n# Pin: %s -> %s (the repository and its worktrees)\n", pin.Repo, pin.Profile)
		opts.writeIncludeIf(&b, gitdir, norm, "/.git", pin.Profile)
		opts.writeIncludeIf(&b, gitdir, norm, "/.git/worktrees/", pin.Profile)
	}
	return b.String()
}

// writeIncludeIf writes the entry for dir, plus one for its real path when a
// symbolic link makes the two differ.
func (o Options) writeIncludeIf(b *strings.Builder, gitdir, dir, suffix, profile string) {
	for _, d := range o.pathForms(dir) {
		fmt.Fprintf(b, "[includeIf %s]\n", quoteSubsection(gitdir+escapeGlob(d)+suffix))
		writeKV(b, "path", o.profilePath(profile))
	}
}

func (o Options) pathForms(dir string) []string {
	if o.Canonicalize == nil {
		return []string{dir}
	}
	if canonical := o.Canonicalize(dir); canonical != dir {
		return []string{dir, canonical}
	}
	return []string{dir}
}

type rule struct {
	written, norm, profile string
}

func sortedRules(cfg config.Config, home string) []rule {
	var rules []rule
	for _, p := range cfg.Profiles {
		for _, d := range p.Dirs {
			norm, _ := paths.Normalize(d, home) // validated in Generate
			rules = append(rules, rule{written: d, norm: norm, profile: p.ID})
		}
	}
	slices.SortStableFunc(rules, func(a, b rule) int {
		return cmp.Or(cmp.Compare(len(a.norm), len(b.norm)), cmp.Compare(a.norm, b.norm))
	})
	return rules
}

func (o Options) profilePath(id string) string {
	return path.Join(o.ConfigDir, ProfileFile(id))
}

func writeKV(b *strings.Builder, key, value string) {
	fmt.Fprintf(b, "\t%s = %s\n", key, quoteValue(value))
}

// IncludeBody is the content GitPersona manages inside the user's Git
// configuration: a single include of the rules index.
func IncludeBody(rulesPath string) string {
	var b strings.Builder
	b.WriteString("# Managed by GitPersona: run `gitpersona apply` to change it. Do not edit inside this block.\n[include]\n")
	writeKV(&b, "path", rulesPath)
	return b.String()
}
